from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import WorkspaceBoard
from .serializers import WorkspaceBoardSerializer

class WorkspaceBoardDiscoveryView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request):
        team_id = request.query_params.get('team_id')
        if not team_id:
            return Response({"error": "team_id is required"}, status=status.HTTP_400_BAD_REQUEST)

        # Validate that the authenticated user belongs to the requested team
        user_team_ids = list(request.user.teams.values_list('id', flat=True))
        target_team = int(team_id)
        if target_team not in user_team_ids:
            return Response({"error": "Access denied to requested team"}, status=status.HTTP_403_FORBIDDEN)

        boards = WorkspaceBoard.objects.filter(authorized_team_ids__overlap=[target_team])
        serializer = WorkspaceBoardSerializer(boards, many=True)
        return Response({"team_id": target_team, "boards": serializer.data})
